class E001_IteratorAccountCLS:
    def __init__(self, accounts: List[C001_AccountCLS]) -> None:
        self._accounts: List[C001_AccountCLS] = accounts
        self._index: int = 0

    def __iter__(self) -> 'E001_IteratorAccountCLS':
